"""P7 — Risk Map par Pays"""import streamlit as stimport plotly.graph_objects as gofrom config import C, apply_theme, ALERT_COLORSfrom components.kpi_cards import kpi_row, section_title, page_headerfrom data.loader import load_health, load_country_healthISO3 = {    "USA":"USA","Germany":"DEU","Italy":"ITA","United Kingdom":"GBR",    "Spain":"ESP","France":"FRA","The Netherlands":"NLD","Switzerland":"CHE",    "Belgium":"BEL","Japan":"JPN","Austria":"AUT","Poland":"POL",    "Portugal":"PRT","Sweden":"SWE","Hong Kong":"HKG","Canada":"CAN",    "Australia":"AUS","Monaco":"MCO","Denmark":"DNK","Greece":"GRC",    "Singapore":"SGP","South Korea":"KOR","Brazil":"BRA","Latvia":"LVA",    "Romania":"ROU","Lithuania":"LTU","Hungary":"HUN","Ireland":"IRL",    "Liechtenstein":"LIE","South Africa":"ZAF","UAE":"ARE","Thailand":"THA",    "Bulgaria":"BGR","Taiwan":"TWN",}STATUT_COLOR = {"Critique": C["red"], "Attention": C["orange"], "Stable": C["green"]}def render():    page_header("Risk Map par Pays",                "Concentration géographique des vendeurs à risque · segmentation marché", "🌍")    df_health  = load_health()    df_country = load_country_health()    with st.sidebar:        st.markdown(f"<div style='color:{C['muted']};font-size:12px;margin-top:16px;'>FILTRES — RISK MAP</div>",                    unsafe_allow_html=True)        min_sellers = st.slider("Nb vendeurs min.", 5, 100, 20, key="rm_min")        statut_filter = st.multiselect("Statut marché",            options=["Critique","Attention","Stable"],            default=["Critique","Attention","Stable"], key="rm_statut")    df_c = df_country[        (df_country["Nb Vendeurs"] >= min_sellers) &        (df_country["Statut Marché"].isin(statut_filter))    ].copy()    df_c["ISO3"]               = df_c["Pays"].map(ISO3)    df_c["% Alertes HIGH pct"] = df_c["% Alertes HIGH"] * 100    critique = df_c[df_c["Statut Marché"] == "Critique"]    kpi_row([        {"title":"Pays analysés","value":f"{len(df_c)}","subtitle":f"Filtre : ≥{min_sellers} vendeurs","color":"blue","icon":"🌍"},        {"title":"Marchés critiques","value":f"{len(critique)}","subtitle":"Statut Critique","color":"red","icon":"🔴"},        {"title":"Pire marché HS moy.","value":df_c.nsmallest(1,"Health Score Moy.")["Pays"].values[0] if len(df_c)>0 else "—","subtitle":f"HS {df_c['Health Score Moy.'].min():.3f}" if len(df_c)>0 else "","color":"orange","icon":"⚠️"},        {"title":"Meilleur marché","value":df_c.nlargest(1,"% Vendeurs OK")["Pays"].values[0] if len(df_c)>0 else "—","subtitle":f"{df_c['% Vendeurs OK'].max()*100:.1f}% OK" if len(df_c)>0 else "","color":"green","icon":"✅"},    ])    section_title("Concentration des alertes HIGH par pays", "🗺️")    df_map = df_c.dropna(subset=["ISO3"])    fig_map = go.Figure(go.Choropleth(        locations=df_map["ISO3"], z=df_map["% Alertes HIGH pct"],        text=df_map["Pays"],        customdata=df_map[["Nb Vendeurs","Health Score Moy.","Statut Marché"]],        colorscale=[[0,C["card"]],[0.35,C["blue"]],[0.65,C["orange"]],[1,C["red"]]],        zmin=0, zmax=100,        marker_line_color=C["border"], marker_line_width=0.5,        colorbar=dict(title=dict(text="% HIGH", font=dict(color=C["muted"])),                      tickfont=dict(color=C["muted"])),        hovertemplate=(            "<b>%{text}</b><br>% HIGH : <b>%{z:.1f}%</b><br>"            "Nb vendeurs : <b>%{customdata[0]}</b><br>"            "HS moy. : <b>%{customdata[1]:.3f}</b><br>"            "Statut : <b>%{customdata[2]}</b><extra></extra>"),    ))    apply_theme(fig_map, "% de vendeurs avec alerte HIGH par pays")    fig_map.update_layout(        height=430,        geo=dict(bgcolor=C["bg"], showframe=False,                 showcoastlines=True, coastlinecolor=C["border"],                 showland=True, landcolor=C["card"],                 showocean=True, oceancolor=C["bg"],                 projection_type="natural earth"))    st.plotly_chart(fig_map, use_container_width=True)    col1, col2 = st.columns([3, 2])    with col1:        section_title("% Alertes HIGH par pays (top 15)", "📊")        df_bar = df_c.nlargest(15,"Nb Vendeurs").sort_values("% Alertes HIGH pct")        fig_bar = go.Figure(go.Bar(            y=df_bar["Pays"], x=df_bar["% Alertes HIGH pct"], orientation="h",            marker=dict(color=[STATUT_COLOR.get(s,C["blue"]) for s in df_bar["Statut Marché"]],                        opacity=0.85, line=dict(color=C["bg"], width=0.5)),            text=[f" {v:.1f}%" for v in df_bar["% Alertes HIGH pct"]],            textposition="outside", textfont=dict(color=C["text"], size=11),            hovertemplate="<b>%{y}</b><br>% HIGH : <b>%{x:.1f}%</b><extra></extra>",        ))        apply_theme(fig_bar, "Couleur = statut marché")        fig_bar.update_layout(height=420, margin=dict(r=60))        st.plotly_chart(fig_bar, use_container_width=True)    with col2:        section_title("Nb vendeurs vs % Alertes", "🫧")        fig_sc = go.Figure()        for statut, grp in df_c.groupby("Statut Marché"):            fig_sc.add_trace(go.Scatter(                x=grp["Nb Vendeurs"], y=grp["% Alertes HIGH pct"],                mode="markers+text", name=statut,                marker=dict(size=12, opacity=0.85,                            color=STATUT_COLOR.get(statut,C["blue"]),                            line=dict(color=C["bg"], width=1.5)),                text=grp["Pays"], textposition="top center",                textfont=dict(color=C["muted"], size=9),                hovertemplate=f"<b>%{{text}}</b><br>%{{x}} vendeurs<br>%{{y:.1f}}% HIGH<extra></extra>",            ))        apply_theme(fig_sc, "")        fig_sc.update_layout(height=420)        fig_sc.update_xaxes(title_text="Nb vendeurs")        fig_sc.update_yaxes(title_text="% Alertes HIGH")        st.plotly_chart(fig_sc, use_container_width=True)    section_title("Lien vers drill-down", "🔍")    pays_options = ["Tous"] + sorted(df_health["Pays"].dropna().unique().tolist())    selected = st.selectbox("Filtrer P8 par pays", pays_options, key="rm_pays")    if selected != "Tous":        st.session_state["filter_pays"] = selected        st.info(f"🔍 Filtre **{selected}** actif → allez en **P8 · Drill-down Vendeur**")